def wide(p):
 p=Path(p).resolve()
 return Path('\\\\?\\'+str(p)) if os.name=='nt' and not str(p).startswith('\\\\?\\') else p
def sha(raw):return hashlib.sha256(raw).hexdigest()
def apply_and_record(path,text,output):
 if path!=RECIPE['path']:return text,None
 root=Path(__file__).resolve().parents[1]/'upstream-slices'/'v034-on-demand'
 raw=wide(root/'manifest.json').read_bytes();assert sha(raw)==ORIGINAL_MANIFEST_SHA256
 manifest=json.loads(raw);assert manifest['upstreamCommit']==COMMIT
 source=next(row for row in manifest['sources'] if row['file']=='VideoRepository.kt')
 raw=wide(root/'VideoRepository.kt').read_bytes()
 assert len(raw)==source['bytes'] and sha(raw)==source['sha256']==ORIGINAL_SHA256
 assert hashlib.sha1(('blob '+str(len(raw))+'\0').encode()+raw).hexdigest()==source['gitBlob']==ORIGINAL_GIT_BLOB
 original=text;assert sha(text.encode())==RECIPE['beforeSha256LF']
 edits=[]
 for edit in RECIPE['edits']:
  before,after=edit['before'],edit['after'];i=edit['offset']
  assert type(i) is int and 0<=i<=len(text)
  assert text[i:i+len(before)]==before
  edits.append(dict(offset=i,before=before,after=after))
  text=text[:i]+after+text[i+len(before):]
 assert sha(text.encode())==RECIPE['afterSha256LF']
 inverse=text
 for edit in reversed(edits):
  i=edit['offset'];assert inverse[i:i+len(edit['after'])]==edit['after']
  inverse=inverse[:i]+edit['before']+inverse[i+len(edit['after']):]
 assert inverse==original
 proof=dict(schemaVersion=1,path=path,upstreamCommit=COMMIT,originalSource=source,
  originalManifest=ORIGINAL_MANIFEST_SHA256,adapter='Windows actual-call local fallback cause preservation',
  beforeSha256LF=RECIPE['beforeSha256LF'],afterSha256LF=RECIPE['afterSha256LF'],inverseEdits=edits,
  actualBoundRequestAuthorityUnchanged=True,successFallbackUnchanged=True,playableSuccessManufactured=False)
 target=wide(Path(output)/(Path(path).name+'.v034-playurl-failure-inverse.json'))
 target.parent.mkdir(parents=True,exist_ok=True)
 target.write_bytes((json.dumps(proof,ensure_ascii=False,indent=2)+'\n').encode())
 return text,proof
